using System;
using System.Collections.Generic;
using System.Linq;
using Comindware.Data.Entity;
using Comindware.TeamNetwork.Api.Data.UserCommands;

public class Script
{

    public static UserCommandResult Main(UserCommandContext userCommandContext, Comindware.Entities entities)
    {
        var parameter_for_search = new Dictionary<string, object>
        {
            { "RequesterAccount_calc", userCommandContext.CurrentUserId } 
        };

        var individual_data_list = Api.TeamNetwork.ObjectService.List("PMSettings_calc",parameter_for_search, null,  new []{"id"} );
        if (individual_data_list.Count() != 0 )
        {
            List<string> legal_entity_list = new List<string>();
            foreach (var relation_data in individual_data_list)
            { 
                var legal_entity_id = getValue("id", relation_data);
                if(!legal_entity_list.Contains(legal_entity_id))
                {
                    legal_entity_list.Add(legal_entity_id);
                }

            }

            if (legal_entity_list.Count() == 1)
            {
                var result = new UserCommandResult()
                {
                    Success = true,
                    Commited = true,
                    ResultType =  UserCommandResultType.Navigate ,
                    NavigationResult = new UserCommandNavigationResult
                    {
                        ContainerId = "oa.33",
                        ObjectId = legal_entity_list[0],
                        Context = ContextType.Record
                        }
                };
                return result;
            }
            else if(legal_entity_list.Count() > 1)
            {
                var result = new UserCommandResult()
                {
                    Success = false,
                    Messages = new[]
                    {
                        new UserCommandMessage
                        {
                            Severity = SeverityLevel.Normal,
                            Text = "ERROR! User has multiple settings!"
                            }
                    },
                    ResultType = UserCommandResultType.Notificate,

                };
                return result;
            }
            else
            {
                var result = new UserCommandResult()
                {
                    Success = false,
                    Messages = new[]
                    {
                        new UserCommandMessage
                        {
                            Severity = SeverityLevel.Normal,
                            Text = "Error! No settings template for current user!"
                            }
                    },
                    ResultType = UserCommandResultType.Notificate,

                };
                return result;
            }


        }
        else
        {
            var result = new UserCommandResult()
            {
                Success = false,
                Messages = new[]
                {
                    new UserCommandMessage
                    {
                        Severity = SeverityLevel.Normal,
                        Text = "No settings template for current user!"
                        }
                },
                ResultType = UserCommandResultType.Notificate,

            };
            return result;
        }






    }
    public static string getValue(string key, IDictionary<string, object> dictionary = null)//функция получения строкового значение ключа из словоря //Input: key and dictionary //Output: null value of key
    {
        if (dictionary == null || key == null)
        {
            return null;
        }
        if (dictionary.TryGetValue(key, out var result))
        {
            if (result == null) return null;
            return result.ToString();
        }
        else
        {
            return null;
        }
    }
}
